mapper.update:
UPDATE exam_record
SET answers = #{answers}, score = #{score}, objective_score = #{objectiveScore}, status = #{status},
    submittime = #{submittime}, used_seconds = #{usedSeconds}, switch_count = #{switchCount},
    auto_submit = #{autoSubmit}, ai_comment = #{aiComment}
WHERE id = #{id}

mapper.select:
SELECT er.*, s.studentname, s.studentno FROM exam_record er LEFT JOIN student s ON er.studentid = s.studentid WHERE er.examid = #{examid}
AND (s.studentname LIKE CONCAT('%', #{keyword}, '%') OR s.studentno LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY er.score DESC, er.submittime ASC
